    #     ell_beta(kappa) = kappa/2 - log2 + log(1+e^-kappa)  [alpha-livre NA ESTRUTURA].
    def _ell_2lvl(k):
        return -np.log(2.0) + k / 2.0 + np.log(1.0 + np.exp(-k))
    lo, hi = 1.0, 40.0                                          # kappa* que casa o alvo (alpha SO' na validacao)
