    U, _ = np.linalg.qr(Xr); AdU = np.kron(U.conj(), U)
    Dc2 = np.kron((U @ Jd @ _fam_dag(U)).conj(), (U @ Jd @ _fam_dag(U))) - np.eye(n * n)
    Db2 = np.kron((U @ S2 @ _fam_dag(U)).conj(), (U @ S2 @ _fam_dag(U))) - np.eye(n * n)
