    ctrl_a = bool(abs(trP - 1.0) > 0.5)     # (a) SEM normalizacao tau(I)=Tr(P_F)=rank != 1 -> 1=1 falha
    Yr = rng.standard_normal((n * n, max(rankF, 1))) + 1j * rng.standard_normal((n * n, max(rankF, 1)))
