def _sci(x, nd=3):
    # v164: guarda de NaN/inf -- numero ausente vira marca legivel, jamais TeX quebrado
    try:
        x = float(x)
    except Exception:
        return r"\text{(aguardando dado)}"
    if x != x or abs(x) == float("inf"):
        return r"\text{(aguardando dado)}"
    if x == 0:
        return "0"
    e = int(math.floor(math.log10(abs(x)))); m = x / 10 ** e
    return "%.*f\\times10^{%d}" % (nd, m, e)


