def _tex_guard_nan(t):
    # v164: dado ausente JAMAIS quebra o TeX -- 'nan' colado em comando ou solto
    # vira marca legivel (fail-closed na leitura: sem dado, sem numero).
    import re as _re
    _b = chr(92)
    t = _re.sub("(" + _b + _b + "[A-Za-z]+)nan(?![A-Za-z])",
                lambda m: m.group(1) + " " + _b + "text{(aguardando dado)}", t)
    t = _re.sub("(?<![A-Za-z])nan(?![A-Za-z])",
                lambda m: _b + "text{--}", t)
    return t

def _tex_to_txt(tex):
    """v168 [ordem do operador, 19/08/2026: os dois artigos em PDF E TXT] --
    conversao LaTeX -> texto plano, sem dependencias: preambulo removido,
    comandos de estilo dissolvidos preservando o texto, secoes marcadas,
    matematica mantida como esta (legivel). Nada do CONTEUDO se perde."""
    import re as _re
    t = tex
    m = _re.search(r"\\begin\{document\}(.*)\\end\{document\}", t, _re.DOTALL)
    if m:
        t = m.group(1)
    t = _re.sub(r"(?<!\\)%[^\n]*", "", t)
    t = t.replace("\\bTGL", "β_TGL").replace("\\Msun", "M_sol")
    t = _re.sub(r"\\TGL(?![A-Za-z])", "TGL", t)
    for _cmd, _sym in (("neq", "≠"), ("to", "→"), ("rightarrow", "→"),
                       ("longrightarrow", "→"), ("Rightarrow", "⟹"),
                       ("Leftrightarrow", "⟺"), ("Longleftrightarrow", "⟺"),
                       ("iff", "⟺"),
                       # v177: simbolos que a subsecao da dobra usa (o TXT da v177
                       # mostrou "$ _n T_n= $" no lugar de "⋂_n T_n=⊥" — defeito de
                       # forma REGISTRADO e corrigido aqui; vale da proxima rodada)
                       ("bigcap", "⋂"), ("bigcup", "⋃"), ("bot", "⊥"), ("top", "⊤"),
                       ("ell", "ℓ"), ("forall", "∀"), ("exists", "∃"),
                       ("subseteq", "⊆"), ("supseteq", "⊇"), ("perp", "⊥"),
                       ("leftrightarrow", "↔"), ("mapsto", "↦"),
                       ("le", "≤"), ("leq", "≤"), ("ge", "≥"), ("geq", "≥"),
                       ("approx", "≈"), ("sim", "~"), ("times", "×"),
                       ("cdot", "·"), ("pm", "±"), ("infty", "∞"),
                       ("partial", "∂"), ("nabla", "∇"), ("sqrt", "√"),
                       ("sum", "Σ"), ("int", "∫"), ("oint", "∮"),
                       ("subseteq", "⊆"), ("subset", "⊂"), ("in", "∈"),
                       ("cap", "∩"), ("cup", "∪"), ("emptyset", "∅"),
                       ("forall", "∀"), ("exists", "∃"), ("implies", "⟹"),
                       ("alpha", "α"), ("beta", "β"), ("gamma", "γ"),
                       ("delta", "δ"), ("epsilon", "ε"), ("varepsilon", "ε"),
                       ("theta", "θ"), ("vartheta", "θ"), ("kappa", "κ"),
                       ("lambda", "λ"), ("mu", "μ"), ("nu", "ν"),
                       ("xi", "ξ"), ("pi", "π"), ("rho", "ρ"),
                       ("sigma", "σ"), ("tau", "τ"), ("phi", "φ"),
                       ("varphi", "φ"), ("chi", "χ"), ("psi", "ψ"),
                       ("omega", "ω"), ("Gamma", "Γ"), ("Delta", "Δ"),
                       ("Theta", "Θ"), ("Lambda", "Λ"), ("Xi", "Ξ"),
                       ("Pi", "Π"), ("Sigma", "Σ"), ("Phi", "Φ"),
                       ("Psi", "Ψ"), ("Omega", "Ω"), ("ell", "ℓ"),
                       ("hbar", "ℏ")):
        t = _re.sub(r"\\" + _cmd + r"(?![A-Za-z])", _sym, t)
    t = _re.sub(r"\\mathcal\s*\{?([A-Z])\}?", r"\1", t)
    t = _re.sub(r"\\math(?:rm|bf|it|sf|bb|frak)\s*\{([^{}]*)\}", r"\1", t)
    t = t.replace("\\ ", " ")
    # ── v305 [O JUIZO DE 31/08: o txt e' a superficie de leitura DECLARADA das
    # IAs (llms.txt) e servia o titulo decapitado, a Meia-Nat como "12 nat",
    # refs "( )" e 19 titulos PT colados no corpo] ─────────────────────────────
    # (a) acentos LaTeX -> UTF-8 ANTES do parse de secoes (titulos com \c{c}
    #     quebravam o regex de secao e o titulo colava no corpo):
    for _acc, _ch in (("\\'a", "á"), ("\\'e", "é"), ("\\'i", "í"), ("\\'o", "ó"),
                      ("\\'u", "ú"), ("\\'A", "Á"), ("\\'E", "É"), ("\\'O", "Ó"),
                      ("\\`a", "à"), ("\\~a", "ã"), ("\\~o", "õ"), ("\\~A", "Ã"),
                      ("\\^a", "â"), ("\\^e", "ê"), ("\\^o", "ô"),
                      ("\\c{c}", "ç"), ("\\c{C}", "Ç")):
        t = t.replace(_acc, _ch)
    t = _re.sub(r"\\i(?![A-Za-z])", "i", t)
    # (b) fracoes: \tfrac12 / \frac{a}{b} -- o numero central da teoria nao
    #     pode ler-se como "12":
    t = _re.sub(r"\\[td]?frac\s*\{([^{}]*)\}\s*\{([^{}]*)\}", r"(\1/\2)", t)
    t = _re.sub(r"\\[td]?frac\s*(\d)\s*(\d)", r"\1/\2", t)
    # (c) comandos de tamanho/forma dissolvidos COM espaco ANTES do laco de
    #     textbf ("\Huge\textbf{Um: Absoluto}" virava "\HugeUm" e o txt perdia
    #     o proprio nome na linha 1):
    t = _re.sub(r"\\(?:Huge|huge|LARGE|Large|large|small|footnotesize|scriptsize|"
                r"normalsize|itshape|bfseries|scshape|centering|noindent|raggedright)(?![A-Za-z])",
                " ", t)
    # (d) referencias internas: "\S\ref{sec:x}" saia como "( )":
    t = _re.sub(r"\\S\\ref\{sec:([^{}]*)\}", r"§[\1]", t)
    t = _re.sub(r"\\ref\{sec:([^{}]*)\}", r"[\1]", t)
    # (e) href mantem o TEXTO (ORCID/DOI saiam duplicados "ab"):
    t = _re.sub(r"\\href\{[^{}]*\}\{([^{}]*)\}", r"\1", t)
    # (f) figuras: IfFileExists + includegraphics com [opt] (o nome da figura
    #     saia DUAS vezes no txt):
    t = _re.sub(r"\\IfFileExists\{[^{}]*\}", "", t)
    t = _re.sub(r"\\includegraphics(\[[^\]]*\])?\{[^{}]*\}", "", t)
    t = _re.sub(r"\\parbox\{[^{}]*\}", "", t)
    # (g) quebras com dimensao ("\\[4pt]" deixava "[4pt]" orfao no cabecalho):
    t = _re.sub(r"\\\\\[[0-9.]+(?:pt|em|ex|mm|cm)\]", "\n", t)
    # (h) o sublinhado escapado (426 "\_" nos vereditos) e o apostrofo:
    t = t.replace("\\_", "_")
    t = t.replace("\\textquotesingle ", "'").replace("\\textquotesingle", "'")
    # (i) funcoes matematicas preservam o NOME ("\sin^2" saia como "^2";
    #     "\circ" e "\S" eram comidos):
    for _fn in ("arcsin", "arccos", "arctan", "sinh", "cosh", "tanh", "sech",
                "sin", "cos", "tan", "log", "ln", "exp", "det", "dim", "ker"):
        t = _re.sub(r"\\" + _fn + r"(?![A-Za-z])", _fn, t)
    t = _re.sub(r"\\circ(?![A-Za-z])", "°", t)
    t = _re.sub(r"\\S(?![A-Za-z])", "§", t)
    t = _re.sub(r"\\(?:sub)*section\*?\{([^{}]*)\}",
                lambda mm: "\n\n== " + mm.group(1) + " ==\n", t)
    t = _re.sub(r"\\paragraph\*?\{([^{}]*)\}",
                lambda mm: "\n-- " + mm.group(1) + " --\n", t)
    t = _re.sub(r"\\begin\{[A-Za-z*]+\}(\[[^\]]*\])?", "", t)
    t = _re.sub(r"\\end\{[A-Za-z*]+\}", "", t)
    for _ in range(6):
        # v305: footnote ganha parenteses proprios -- antes o texto da nota
        # colava no corpo ("publicadoRemissão").
        t = _re.sub(r"\\footnote\{([^{}]*)\}", r" (nota: \1)", t)
        t = _re.sub(r"\\(?:textbf|textit|emph|texttt|textsf|textrm|mathrm|text|mbox|"
                    r"underline|kernelmk)\{([^{}]*)\}", r"\1", t)
    t = _re.sub(r"\\(?:label|ref|eqref|cite|hypertarget|hyperlink|includegraphics|"
                r"input|bibliography|bibliographystyle)\{[^{}]*\}", "", t)
    t = _re.sub(r"\\item\b", "\n * ", t)
    t = t.replace("\\\\", "\n")
    t = _re.sub(r"\\[A-Za-z@]+(\[[^\]]*\])?", " ", t)
    t = t.replace("~", " ").replace("{", "").replace("}", "")
    t = _re.sub(r"[ \t]+", " ", t)
    t = _re.sub(r" *\n *", "\n", t)
    t = _re.sub(r"\n{3,}", "\n\n", t)
    return t.strip() + "\n"


def emit_article(core, verdict, data_path, lang):
    if lang == "pt":
        p = os.path.join(OUT, "um_absoluto_pt.tex")
        _tx = _tex_guard_nan(build_pt(core, verdict, data_path))
        open(p, "w", encoding="utf-8").write(_tx)
        open(os.path.join(OUT, "um_absoluto_pt.txt"), "w",
             encoding="utf-8").write(_tex_to_txt(_tx))          # v168: PDF E TXT
        return p
    p = os.path.join(OUT, "um_absoluto_en.tex")
    _tx = _tex_guard_nan(build_en(core, verdict, data_path))
    open(p, "w", encoding="utf-8").write(_tx)
    open(os.path.join(OUT, "um_absoluto_en.txt"), "w",
         encoding="utf-8").write(_tex_to_txt(_tx))              # v168: PDF E TXT
    return p


def compile_pdf(texname):
    """v184 [TRAVA DO PDF]: retorno TRI-ESTADO, para separar o que e' falha do que
    nao e'.  None = pdflatex AUSENTE (caminho gracioso: o .tex sai e quem nao tem
    TeX ainda reproduz o resto; o selo NAO pode depender do ambiente).  False =
    motor PRESENTE e o PDF NAO saiu -> FALHA REAL, e o chamador trava.  True = ok.
    Achado da v183: os dois retornos eram descartados e o selo avancava com o PDF
    ausente -- um passo que nao podia reprovar."""
    eng = shutil.which("pdflatex")
    if not eng:
        print("   [PDF] pdflatex ausente -> .tex gerado; compile com MiKTeX/TeX Live."); return None
    try:
        for _ in range(2):
            subprocess.run([eng, "-interaction=nonstopmode", "-halt-on-error", texname + ".tex"],
                           cwd=OUT, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=180)
        ok = os.path.exists(os.path.join(OUT, texname + ".pdf"))
        print("   [PDF] %s.pdf %s" % (texname, "OK" if ok else "FALHOU (ver %s.log)" % texname))
        return ok
    except Exception as e:
        print("   [PDF] erro:", e); return False


